import type { Card, Note, Source, Topic } from '../domain';

const topicId = 'cc-telephony';
const noteId = (n: number) => `${topicId}-note-${String(n).padStart(2, '0')}`;
const verified = '2026-10-09';

function recall(
  n: number, difficulty: Card['difficulty'], prompt: string, answer: string,
  checkpoints: string[], tags: string[], sourceIds: string[], note: number,
): Card {
  return { id: `${topicId}-${String(n).padStart(3, '0')}`, topicId, revision: 1,
    kind: 'recall', difficulty, prompt, answer, checkpoints, tags, sourceIds, noteIds: [noteId(note)] };
}

function mcq(
  n: number, difficulty: Card['difficulty'], prompt: string, answer: string,
  checkpoints: string[], tags: string[], sourceIds: string[], note: number,
  correctOptionId: 'a' | 'b' | 'c' | 'd',
  choices: [string, string, string, string], rationales: [string, string, string, string],
): Card {
  return { ...recall(n, difficulty, prompt, answer, checkpoints, tags, sourceIds, note),
    kind: 'mcq', correctOptionId,
    options: choices.map((text, i) => ({ id: ['a', 'b', 'c', 'd'][i], text, rationale: rationales[i] })) };
}

function note(
  n: number, title: string, summary: string, checklist: string[], gotchas: string[],
  tags: string[], sourceIds: string[],
): Note {
  return { id: noteId(n), topicId, title, summary,
    sections: [{ heading: 'Implementation checklist', bullets: checklist },
      { heading: 'Gotchas and verification', bullets: gotchas }], tags, sourceIds };
}

